"""Generated bytes and signed targets only; no real bucket or external IO."""

import base64
import hashlib
import hmac
import re
import select
import ssl
import threading
import time
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import unquote

BLOCK = bytes(range(256)) * 256
ETAG = '"object-representation"'
MODIFIED = "Wed, 21 Oct 2015 07:28:00 GMT"
OLD = "Wed, 21 Oct 2015 07:27:00 GMT"
FUTURE = "Wed, 21 Oct 2037 07:28:00 GMT"


class Peer(ThreadingHTTPServer):
    daemon_threads = True

    def __init__(self, ak, sk, certificate=None, key=None):
        super().__init__(("127.0.0.1", 0), Handler)
        self.ak, self.sk = ak, sk
        self.origin = ""
        self.seen = []
        self.sni = []
        self.size = 65536
        self.delay = 0
        self.mode = "normal"
        if certificate:
            ctx = ssl.SSLContext(ssl.PROTOCOL_TLS_SERVER)
            ctx.load_cert_chain(certificate, key)
            ctx.set_servername_callback(lambda _sock, name, _ctx: self.sni.append(name))
            self.socket = ctx.wrap_socket(self.socket, server_side=True)
        self.thread = threading.Thread(target=self.serve_forever, daemon=True)
        self.thread.start()

    def close(self):
        self.shutdown()
        self.server_close()
        self.thread.join()

    def handle_error(self, *_args):
        pass


class Handler(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"

    def log_message(self, *_args):
        pass

    def do_HEAD(self):
        self.do_GET()

    def do_GET(self):
        p = self.server
        observation = {
            "method": self.command,
            "target": self.path,
            "headers": dict(self.headers),
            "bytes": 0,
            "start": time.monotonic(),
            "end": None,
        }
        p.seen.append(observation)
        try:
            self.send_object(p, observation)
        except (OSError, ssl.SSLError):
            observation["cancelled"] = True
        finally:
            observation["end"] = time.monotonic()
            self.close_connection = True

    def send_object(self, p, observation):
        signed, separator, token = self.path.rpartition("&token=")
        expected = (
            p.ak
            + ":"
            + base64.urlsafe_b64encode(
                hmac.new(
                    p.sk.encode(), (p.origin + signed).encode(), hashlib.sha1
                ).digest()
            ).decode()
        )
        if not separator or not hmac.compare_digest(token, expected):
            self.send_response(403)
            self.send_header("Content-Length", "0")
            self.end_headers()
            observation["bad_signature"] = True
            return
        key = unquote(self.path.split("?", 1)[0][1:])
        mode = (
            key
            if key.startswith(
                (
                    "error-",
                    "short",
                    "stall",
                    "drip",
                    "ignore",
                    "controls",
                    "cancel-head",
                )
            )
            else p.mode
        )
        size, delay = p.size, p.delay
        if mode in {"stall-head", "cancel-head"}:
            deadline = time.monotonic() + (10 if mode == "cancel-head" else 2)
            while time.monotonic() < deadline:
                if select.select([self.connection], [], [], 0.02)[0]:
                    if not self.connection.recv(1):
                        observation["cancelled"] = True
                        return
        status = int(mode[6:]) if mode.startswith("error-") else 200
        start, end = 0, size - 1
        # RFC precedence is deliberately owned by the fake ENTITY server.
        if status == 200:
            match = self.headers.get("If-Match")
            none = self.headers.get("If-None-Match")
            if match and match not in {ETAG, "*"}:
                status = 412
            elif not match and self.headers.get("If-Unmodified-Since") == OLD:
                status = 412
            elif none and (ETAG in none or none == "*"):
                status = 304
            elif not none and self.headers.get("If-Modified-Since") in {
                MODIFIED,
                FUTURE,
            }:
                status = 304
        rng = self.headers.get("Range")
        if_range = self.headers.get("If-Range")
        if (
            status == 200
            and rng
            and mode != "ignore-range"
            and (not if_range or if_range in {ETAG, MODIFIED, FUTURE})
        ):
            m = re.fullmatch(r"bytes=(\d*)-(\d*)", rng)
            if m and any(m.groups()):
                a, b = m.groups()
                start = int(a) if a else max(0, size - int(b))
                end = min(size - 1, int(b)) if a and b else size - 1
                if start >= size or end < start or (not a and int(b) == 0):
                    status = 416
                else:
                    status = 206
        error = status not in {200, 206, 304}
        body = b'{"upstream":"rejected"}' if error else None
        length = len(body) if error else max(0, end - start + 1)
        self.send_response(status)
        self.send_header("Connection", "close")
        if status != 304:
            self.send_header("Content-Length", str(length))
        self.send_header("ETag", ETAG)
        self.send_header("Last-Modified", MODIFIED)
        self.send_header(
            "Content-Type", "application/json" if error else "text/upstream-untrusted"
        )
        self.send_header("Accept-Ranges", "bytes")
        if status == 206:
            self.send_header("Content-Range", f"bytes {start}-{end}/{size}")
        if status == 416:
            self.send_header("Content-Range", f"bytes */{size}")
        if status == 401:
            self.send_header("WWW-Authenticate", 'Basic realm="object"')
        if 300 <= status < 400 and status != 304:
            self.send_header("Location", "https://redirect.invalid/private")
        if mode == "cacheable":
            self.send_header("Cache-Control", "public, max-age=60")
        if mode == "controls":
            self.send_header("X-Accel-Redirect", "/should-never-run")
            self.send_header("X-Accel-Buffering", "yes")
            self.send_header("X-Accel-Limit-Rate", "1")
            self.send_header("Set-Cookie", "upstream=private")
            self.send_header("Access-Control-Allow-Origin", "https://wrong.invalid")
        self.end_headers()
        self.wfile.flush()
        if self.command == "HEAD" or status == 304:
            return
        if body:
            self.wfile.write(body)
            return
        if mode == "stall-body":
            self.wfile.write(BLOCK[:1])
            self.wfile.flush()
            time.sleep(2)
        left = length // 2 if mode == "short" else length
        if mode == "drip":
            left = 20
        pos = start
        while left:
            count = min(left, 1 if mode == "drip" else len(BLOCK))
            chunk = (BLOCK + BLOCK)[pos % len(BLOCK) : pos % len(BLOCK) + count]
            self.wfile.write(chunk)
            self.wfile.flush()
            observation["bytes"] += count
            left -= count
            pos += count
            if delay or mode == "drip":
                time.sleep(0.1 if mode == "drip" else delay)
